//! 📤️ Output bytes retain original paged backing until paid transfer and physical retirement.
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_persistent::list::PagedList;
use std::mem::{size_of,ManuallyDrop};
use super::{MAX_LAYOUT_EXPORT_OUTPUT_BYTES,OUTPUT_CHUNK_BYTES};
#[path="📝️text/🦀️.rs"]mod text;
pub(super) const OUTPUT_BODY_BYTES:usize=8192;
pub(super) const OUTPUT_COPY_BYTES:usize=(OUTPUT_BODY_BYTES+HEADER_BYTES)*2;
const TRANSFER_BYTES:usize=512;
const HEADER_BYTES:usize=std::mem::size_of::<usize>()*3;
fn fault(reason:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,reason)}
fn fits(d:RetirementDemand,g:RetainedCloneGrant)->bool{g.maximum_items>0&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes&&g.maximum_depth>=d.depth}
/// 🎟️ Every byte emission forwards one original turn grant and returns its exact aggregate effects.
pub(super) struct OutputWork{grant:RetainedCloneGrant,actual:RetainedCloneProgress,preparatory:bool}
impl OutputWork{
 pub fn new(grant:RetainedCloneGrant)->Self{Self{grant,actual:Default::default(),preparatory:false}}
 pub fn receipt(&self)->RetainedCloneProgress{self.actual}
 pub fn mark_preparatory(&mut self){self.preparatory=true;}
 pub fn is_preparatory(&self)->bool{self.preparatory}
 pub fn byte_buffer(&mut self,value:&mut Vec<u8>,length:usize)->Result<bool,String>{if value.capacity()>=length{return Ok(true);}if value.capacity()!=0{return Err("layout-output-contiguous-source-changed".into());}self.preparatory=true;let remaining=self.remaining();let copy_bytes=size_of::<Vec<u8>>()*2;if remaining.maximum_items==0||remaining.maximum_copy_bytes<copy_bytes||remaining.maximum_capacity_bytes<length||remaining.maximum_depth==0{return Ok(false);}let result=value.try_reserve_exact(length);let progress=RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,retained_capacity_bytes:value.capacity(),..Default::default()};self.consume(progress)?;result.map_err(|_|"layout-output-contiguous-allocation-failed")?;Ok(false)}
 pub fn remaining(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.grant.maximum_items.saturating_sub(self.actual.copied_items),maximum_copy_bytes:self.grant.maximum_copy_bytes.saturating_sub(self.actual.copied_bytes),maximum_capacity_bytes:self.grant.maximum_capacity_bytes.saturating_sub(self.actual.retained_capacity_bytes),maximum_release_bytes:self.grant.maximum_release_bytes.saturating_sub(self.actual.released_bytes),maximum_depth:self.grant.maximum_depth}}
 pub fn consume(&mut self,progress:RetainedCloneProgress)->Result<(),&'static str>{let admitted=progress.fits(self.remaining());self.actual=self.actual.checked_add(progress).map_err(|_|"layout output child receipt overflow")?;if admitted{Ok(())}else{Err("layout output child exceeded original remaining grant")}}
 pub fn ready(&self,depth:usize)->bool{self.grant.maximum_items>=32&&self.grant.maximum_copy_bytes>=OUTPUT_COPY_BYTES&&self.grant.maximum_depth>=depth}
 pub(super) fn copy(&mut self,bytes:usize,depth:usize)->Result<(),String>{let total=self.actual.copied_bytes.checked_add(bytes).ok_or("layout-output-copy-overflow")?;if self.actual.copied_items>=self.grant.maximum_items||total>self.grant.maximum_copy_bytes||depth>self.grant.maximum_depth{return Err("layout-output-copy-not-funded".into());}self.actual.copied_bytes=total;self.actual.copied_items+=1;Ok(())}
}
#[derive(Debug)]
pub struct ChunkRope{bytes:ManuallyDrop<PagedList<u8,{usize::MAX}>>,pub len:usize,pub digest:u64,read_cursor:usize,transfer:ManuallyDrop<Vec<u8>>,transfer_length:usize,pub(super) publishing:ManuallyDrop<Option<Vec<u8>>>}
impl ChunkRope{
 pub fn new()->Self{Self{bytes:ManuallyDrop::new(PagedList::empty()),len:0,digest:0xcbf29ce484222325,read_cursor:0,transfer:ManuallyDrop::new(Vec::new()),transfer_length:0,publishing:ManuallyDrop::new(None)}}
 pub fn allocated_bytes(&self)->usize{self.bytes.allocated_bytes()+self.transfer.capacity()+self.publishing.as_ref().map_or(0,Vec::capacity)}
 pub fn terminal_is_empty(&self)->bool{self.bytes.terminal_is_empty()&&self.transfer.capacity()==0&&self.publishing.is_none()}
 pub fn has_room(&self,body:usize)->bool{self.bytes.capacity().saturating_sub(self.bytes.len())>=body.min(MAX_LAYOUT_EXPORT_OUTPUT_BYTES.saturating_sub(self.len))}
 pub fn write_depth(&self)->Result<usize,ValueError>{self.bytes.next_push_depth_demand().map_err(|_|fault("layout output path demand"))}
 pub fn prepare_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.has_room(body){return Ok(Default::default());}Ok(RetirementDemand{copy_bytes:self.bytes.next_capacity_copy_byte_demand(MAX_LAYOUT_EXPORT_OUTPUT_BYTES).map_err(|_|fault("layout output reservation copy"))?,capacity_bytes:self.bytes.next_capacity_allocation_bytes(MAX_LAYOUT_EXPORT_OUTPUT_BYTES).map_err(|_|fault("layout output reservation capacity"))?.unwrap_or(0),depth:self.bytes.next_capacity_depth_demand(MAX_LAYOUT_EXPORT_OUTPUT_BYTES).map_err(|_|fault("layout output reservation depth"))?,release_bytes:0})}
 pub fn prepare_one(&mut self,body:usize,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.has_room(body){return Ok(RetainedCloneStep::Complete(Default::default()));}let demand=self.prepare_demand(body)?;if !fits(demand,grant){return Ok(RetainedCloneStep::Progress(Default::default()));}let progress=self.bytes.reserve_capacity_one_funded(MAX_LAYOUT_EXPORT_OUTPUT_BYTES,grant).map_err(|error|fault("layout output physical reservation failed").with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:error.allocated_bytes,..Default::default()}))?;Ok(RetainedCloneStep::Progress(progress))}
 pub(super) fn append_format(&mut self,value:std::fmt::Arguments<'_>,work:&mut OutputWork)->Result<(),String>{use std::fmt::Write;let grant=work.remaining();if grant.maximum_items<2||grant.maximum_copy_bytes<OUTPUT_BODY_BYTES+HEADER_BYTES||grant.maximum_depth==0{return Err("layout-output-format-not-funded".into());}let mut text=text::TextFragment::new(OUTPUT_BODY_BYTES)?;let result=text.write_fmt(value);work.copy(text.written().len()+HEADER_BYTES,1)?;result.map_err(|_|"layout-output-text-overflow")?;self.append(text.finish()?,work)}
 pub(super) fn append(&mut self,bytes:&[u8],work:&mut OutputWork)->Result<(),String>{if bytes.is_empty(){return Ok(());}if self.len.checked_add(bytes.len()).is_none_or(|len|len>MAX_LAYOUT_EXPORT_OUTPUT_BYTES){return Err("layout-export-output-limit".into());}if !self.has_room(bytes.len()){return Err("layout-output-backing-not-admitted".into());}let depth=self.write_depth().map_err(|_|"layout-output-path-demand")?;work.copy(bytes.len().checked_add(HEADER_BYTES).ok_or("layout-output-copy-overflow")?,depth)?;for byte in bytes{self.bytes.push_reserved(*byte).map_err(|_|"layout-output-reserved-slot")?;self.digest=(self.digest^u64::from(*byte)).wrapping_mul(0x100000001b3);}self.len+=bytes.len();Ok(())}
 pub(super) fn copy_range(&self,start:usize,target:&mut[u8],work:&mut OutputWork)->Result<(),String>{if start.checked_add(target.len()).is_none_or(|end|end>self.len){return Err("layout-output-read-range".into());}let depth=self.bytes.next_get_depth_demand(start).map_err(|_|"layout-output-read-depth")?;work.copy(target.len()+HEADER_BYTES,depth)?;for(at,out)in target.iter_mut().enumerate(){*out=*self.bytes.get(start+at).ok_or("layout-output-read-address")?;}Ok(())}
 pub fn transfer_demand(&self)->Result<RetirementDemand,ValueError>{let remaining=self.len.saturating_sub(self.read_cursor);if remaining==0&&self.transfer_length==0{return Ok(Default::default());}let length=remaining.min(OUTPUT_CHUNK_BYTES);if self.transfer.capacity()==0{return Ok(RetirementDemand{capacity_bytes:length,copy_bytes:HEADER_BYTES,depth:1,release_bytes:0});}if self.transfer.len()<self.transfer_length{return Ok(RetirementDemand{copy_bytes:(self.transfer_length-self.transfer.len()).min(TRANSFER_BYTES)+HEADER_BYTES,depth:self.bytes.next_get_depth_demand(self.read_cursor+self.transfer.len()).map_err(|_|fault("layout output transfer path"))?,..Default::default()});}Ok(RetirementDemand{copy_bytes:std::mem::size_of::<Vec<u8>>()*2+HEADER_BYTES,depth:1,..Default::default()})}
 pub fn transfer_one(&mut self,grant:RetainedCloneGrant)->Result<(Option<Vec<u8>>,bool,RetainedCloneProgress),ValueError>{if self.read_cursor==self.len&&self.transfer_length==0{return Ok((None,true,Default::default()));}let demand=self.transfer_demand()?;if !fits(demand,grant){return Ok((None,false,Default::default()));}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};if self.transfer.capacity()==0{let length=(self.len-self.read_cursor).min(OUTPUT_CHUNK_BYTES);self.transfer.try_reserve_exact(length).map_err(|_|fault("layout output transfer reservation failed"))?;self.transfer_length=length;p.retained_capacity_bytes=self.transfer.capacity();if p.retained_capacity_bytes>grant.maximum_capacity_bytes{return Err(fault("layout output transfer allocator exceeded original capacity grant").with_retained_progress(p));}return Ok((None,false,p));}if self.transfer.len()<self.transfer_length{let end=(self.transfer.len()+TRANSFER_BYTES).min(self.transfer_length);for at in self.transfer.len()..end{self.transfer.push(*self.bytes.get(self.read_cursor+at).ok_or_else(||fault("layout output transfer source"))?);}return Ok((None,false,p));}let chunk=std::mem::take(&mut *self.transfer);self.read_cursor+=self.transfer_length;self.transfer_length=0;Ok((Some(chunk),false,p))}
 pub fn close_demand(&self)->Result<RetirementDemand,ValueError>{if let Some(chunk)=self.publishing.as_ref(){return Ok(RetirementDemand{release_bytes:chunk.capacity(),copy_bytes:std::mem::size_of::<Vec<u8>>(),depth:1,capacity_bytes:0});}if self.transfer.capacity()>0{return Ok(RetirementDemand{release_bytes:self.transfer.capacity(),depth:1,..Default::default()});}if !self.bytes.is_empty(){return Ok(RetirementDemand{copy_bytes:self.bytes.len().min(OUTPUT_BODY_BYTES)+HEADER_BYTES,depth:self.bytes.next_pop_depth_demand().map_err(|_|fault("layout output retirement path"))?,..Default::default()});}Ok(RetirementDemand{release_bytes:self.bytes.next_release_allocation_bytes().map_err(|_|fault("layout output retirement backing"))?,depth:self.bytes.next_release_depth_demand().map_err(|_|fault("layout output retirement depth"))?,..Default::default()})}
 pub fn close_one(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}let d=self.close_demand()?;if !fits(d,grant){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if self.publishing.is_some(){p.released_bytes=self.publishing.as_ref().map_or(0,Vec::capacity);self.publishing.take();}else if self.transfer.capacity()>0{p.released_bytes=self.transfer.capacity();drop(std::mem::take(&mut *self.transfer));self.transfer_length=0;}else if !self.bytes.is_empty(){for _ in 0..self.bytes.len().min(OUTPUT_BODY_BYTES){self.bytes.pop();}}else{let step=self.bytes.release_empty_page(grant.maximum_release_bytes).map_err(|_|fault("layout output physical retirement failed"))?;p.released_bytes=step.released_allocation_bytes;}Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 #[cfg(any(test,feature="testkit"))]pub fn fixture_source_pointer(&self,index:usize)->Option<usize>{self.bytes.backing_ptr(index).map(|pointer|pointer as usize)}
 #[cfg(any(test,feature="testkit"))]pub fn fixture_transfer(&mut self,value:Vec<u8>){self.transfer_length=value.len();*self.transfer=value;}
 #[cfg(any(test,feature="testkit"))]pub fn fixture_transfer_ptr(&self)->usize{self.transfer.as_ptr()as usize}
 #[cfg(any(test,feature="testkit"))]pub fn fixture_transfer_capacity(&self)->usize{self.transfer.capacity()}
}
impl Drop for ChunkRope{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(empty||std::thread::panicking(),"layout output retains original byte custody until funded retirement");if empty{unsafe{ManuallyDrop::drop(&mut self.bytes);ManuallyDrop::drop(&mut self.transfer);ManuallyDrop::drop(&mut self.publishing);}}}}
